-- Atlas Division pathway ("The Silence") Act 36 -- "Atlas Falls"
-- content, the campaign finale, under world-atlas-atlas-falls (already
-- inserted separately). 1 campaign, 2 operations, 12 missions (11
-- incident stages + the final boss "THE SILENCE"), closing World X
-- "Atlas" and the entire 36-Act Atlas Division campaign.
--
-- Same terminal-engine constraint as every prior Atlas Act. Reuses two
-- existing hosts throughout rather than introducing new ones for a
-- one-Act finale: `atlas-incident-01` (first built in Act 26) holds
-- every stage of the live incident response, and `atlas-observability-01`
-- holds the telemetry-side artifacts (the first alert, the blackout).
-- Every technical fact referenced -- the Act 6 CI runner host, the Act 32
-- policy gate, the Act 27 circuit breaker and load shedding, the Act 29
-- DR plan, the Act 30 platform secrets API, the Act 31 mesh mTLS, the
-- Act 34 regional isolation and traffic steering -- is drawn directly
-- from what those Acts actually built, not invented fresh.
--
-- The final boss is deliberately larger than every prior boss in this
-- pathway: 5 objectives instead of the usual 4, and its investigation
-- (o4) is a retrospective comparison against Act 1's own 03:17 incident
-- rather than a root-cause hunt -- the pathway's one deliberate
-- structural variation reserved for its own finale.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-atlas-atlas-falls', 'world-atlas-atlas-falls', 'atlas-falls', '10D - Atlas Falls', 'The campaign finale. One continuous incident, live, end to end -- a real supply-chain compromise reaches production, and every system this pathway has ever built is tested together for the first time.', 4);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-atlas-atlas-falls-1', 'campaign-atlas-atlas-falls', 'the-compromise-spreads', 'The Compromise Spreads', 'First Alarm, Pipeline Compromise, Registry Failure, Cluster Saturation, Telemetry Blackout and Database Failover.', 1),
  ('operation-atlas-atlas-falls-2', 'campaign-atlas-atlas-falls', 'containing-and-recovering-atlas', 'Containing and Recovering Atlas', 'Queue Backlog, Credential Revocation, Region Isolation, Global Traffic Shift, Recover Atlas, and the final reckoning.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-atlas-atlas-falls-01', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'first-alarm', 'First Alarm', 'An alert fires at 02:58 UTC: anomalous outbound traffic from a CI runner. Nobody yet knows how far this actually goes.', 'advanced', ARRAY['leena','byte'], null, null, '{"type":"simulation","simulationId":"first-alarm-sim"}'::jsonb, '{"xp":760,"credits":55}'::jsonb, false, 1),
  ('mission-atlas-atlas-falls-02', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'pipeline-compromise', 'Pipeline Compromise', 'Confirm exactly which real pipeline was actually compromised, and exactly why it was never protected by Act 32''s own policy gate.', 'advanced', ARRAY['rook'], '{"requiredMissionIds":["mission-atlas-atlas-falls-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"pipeline-compromise-sim"}'::jsonb, '{"xp":760,"credits":55}'::jsonb, false, 2),
  ('mission-atlas-atlas-falls-03', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'registry-failure', 'Registry Failure', 'Confirm exactly how a maliciously built image still passed the registry''s own signature check.', 'advanced', ARRAY['rook'], '{"requiredMissionIds":["mission-atlas-atlas-falls-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"registry-failure-sim"}'::jsonb, '{"xp":770,"credits":55}'::jsonb, false, 3),
  ('mission-atlas-atlas-falls-04', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'cluster-saturation', 'Cluster Saturation', 'Confirm exactly how the compromised image actually saturated real cluster capacity once it deployed.', 'advanced', ARRAY['cross'], '{"requiredMissionIds":["mission-atlas-atlas-falls-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"cluster-saturation-sim"}'::jsonb, '{"xp":770,"credits":60}'::jsonb, false, 4),
  ('mission-atlas-atlas-falls-05', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'telemetry-blackout', 'Telemetry Blackout', 'Confirm exactly how long real telemetry actually went dark, and how the team actually kept working through it.', 'advanced', ARRAY['byte'], '{"requiredMissionIds":["mission-atlas-atlas-falls-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"telemetry-blackout-sim"}'::jsonb, '{"xp":780,"credits":60}'::jsonb, false, 5),
  ('mission-atlas-atlas-falls-06', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-1', 'database-failover', 'Database Failover', 'Confirm exactly how Act 29''s own disaster recovery plan actually performed the moment it was needed for real.', 'advanced', ARRAY['vey'], '{"requiredMissionIds":["mission-atlas-atlas-falls-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"database-failover-sim"}'::jsonb, '{"xp":780,"credits":60}'::jsonb, false, 6),
  ('mission-atlas-atlas-falls-07', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'queue-backlog', 'Queue Backlog', 'Confirm exactly how the team actually drained a real, growing message backlog without losing anything in it.', 'advanced', ARRAY['cross'], '{"requiredMissionIds":["mission-atlas-atlas-falls-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"queue-backlog-sim"}'::jsonb, '{"xp":790,"credits":60}'::jsonb, false, 7),
  ('mission-atlas-atlas-falls-08', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'credential-revocation', 'Credential Revocation', 'Confirm exactly which real credentials the team actually revoked, and how fast the platform''s own API let them do it.', 'advanced', ARRAY['rook'], '{"requiredMissionIds":["mission-atlas-atlas-falls-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"credential-revocation-sim"}'::jsonb, '{"xp":790,"credits":65}'::jsonb, false, 8),
  ('mission-atlas-atlas-falls-09', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'region-isolation', 'Region Isolation', 'Confirm exactly how the team actually cut the compromised region off without taking the other two down with it.', 'advanced', ARRAY['vey'], '{"requiredMissionIds":["mission-atlas-atlas-falls-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"region-isolation-sim"}'::jsonb, '{"xp":800,"credits":65}'::jsonb, false, 9),
  ('mission-atlas-atlas-falls-10', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'global-traffic-shift', 'Global Traffic Shift', 'Confirm exactly how every real customer request was actually rerouted away from the isolated region, automatically.', 'advanced', ARRAY['vey'], '{"requiredMissionIds":["mission-atlas-atlas-falls-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"global-traffic-shift-sim"}'::jsonb, '{"xp":800,"credits":65}'::jsonb, false, 10),
  ('mission-atlas-atlas-falls-11', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'recover-atlas', 'Recover Atlas', 'Confirm exactly how the compromised region was actually rebuilt clean, from the ground up, before it was ever let back in.', 'advanced', ARRAY['rook','vey'], '{"requiredMissionIds":["mission-atlas-atlas-falls-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"recover-atlas-sim"}'::jsonb, '{"xp":810,"credits":70}'::jsonb, false, 11),
  ('mission-atlas-atlas-falls-12', 'world-atlas-atlas-falls', 'campaign-atlas-atlas-falls', 'operation-atlas-atlas-falls-2', 'the-silence', 'The Silence', 'The final reckoning. Thirty-five Acts of hard-won discipline, tested together for real, for the first time -- and the one gap that still slipped through anyway.', 'boss', ARRAY['leena','vey','cross','rook','byte'], '{"requiredMissionIds":["mission-atlas-atlas-falls-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-silence-final-boss-sim"}'::jsonb, '{"xp":1000,"credits":300,"badgeIds":["the-silence"],"skillXp":{"cloud_devops_fundamentals":200}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-atlas-atlas-falls-01', 1, 'byte', 'Alert, 02:58 UTC. Anomalous outbound traffic from atlas-ci-runner-04. It has never made a connection like this before.'),
  ('mission-atlas-atlas-falls-01', 2, 'leena', 'Leena. Every team, on call, now. We do not yet know how far this actually goes. We are about to find out, together.'),

  ('mission-atlas-atlas-falls-02', 1, 'rook', 'Rook. Confirm exactly which real pipeline this actually reached, and exactly why Act 32''s own policy gate never got a chance to stop it.'),

  ('mission-atlas-atlas-falls-03', 1, 'rook', 'A stolen signing key from a compromised pipeline still produces a validly signed image. Confirm exactly how that got past the registry.'),

  ('mission-atlas-atlas-falls-04', 1, 'cross', 'Imani Cross. Confirm exactly how this one malicious image actually saturated real cluster capacity once it started running.'),

  ('mission-atlas-atlas-falls-05', 1, 'byte', 'Telemetry just went dark. The same silence this whole pathway started with. Confirm exactly how long, and how the team kept working anyway.'),

  ('mission-atlas-atlas-falls-06', 1, 'vey', 'Tomas Vey. This is what Act 29 was actually built for. Confirm exactly how the real failover performed, for real, under real pressure.'),

  ('mission-atlas-atlas-falls-07', 1, 'cross', 'Confirm exactly how the team actually drained a real, growing backlog safely, without losing a single message in it.'),

  ('mission-atlas-atlas-falls-08', 1, 'rook', 'Confirm exactly which real credentials this compromise could have touched, and how fast the Act 30 platform''s own API let the team revoke every one of them.'),

  ('mission-atlas-atlas-falls-09', 1, 'vey', 'Confirm exactly how the team actually isolated the compromised region without taking either of the other two down with it.'),

  ('mission-atlas-atlas-falls-10', 1, 'vey', 'Confirm exactly how every real customer request got automatically rerouted away from the isolated region, with nobody manually touching a single DNS record.'),

  ('mission-atlas-atlas-falls-11', 1, 'rook', 'Confirm exactly how the compromised region was actually rebuilt, clean, from real infrastructure-as-code, before it was ever let back into rotation.'),

  ('mission-atlas-atlas-falls-12', 1, 'leena', 'Every stage of this incident, confirmed. Now the real reckoning -- not just what broke, but what held, and why.'),
  ('mission-atlas-atlas-falls-12', 2, 'byte', 'I have the full incident timeline. First Alarm to full, verified recovery: fifty-two minutes, start to finish.'),
  ('mission-atlas-atlas-falls-12', 3, 'rook', 'One real gap made this possible at all -- a single legacy pipeline nobody ever migrated onto the Act 32 gate.'),
  ('mission-atlas-atlas-falls-12', 4, 'cross', 'And everything else -- the mesh, the DR plan, the isolation, the credential rotation -- held. Every single piece of it, exactly as designed.'),
  ('mission-atlas-atlas-falls-12', 5, 'vey', 'Thirty-five Acts ago, 03:17 took days to even understand. This took fifty-two minutes to fully resolve.'),
  ('mission-atlas-atlas-falls-12', 6, 'leena', 'Compare both, honestly, and say what actually changed.');

