  ('mission-atlas-atlas-falls-12-o1', 'mission-atlas-atlas-falls-12', 1, 'Confirm the full incident timeline', 'Read the full incident timeline and submit the verification code.'),
  ('mission-atlas-atlas-falls-12-o2', 'mission-atlas-atlas-falls-12', 2, 'Confirm the root cause', 'Read the confirmed root cause and submit the verification code.'),
  ('mission-atlas-atlas-falls-12-o3', 'mission-atlas-atlas-falls-12', 3, 'Confirm every containment system held', 'Read the containment systems report and submit the verification code.'),
  ('mission-atlas-atlas-falls-12-o4', 'mission-atlas-atlas-falls-12', 4, 'Compare against Act 1''s original incident', 'Find every piece of evidence that shows what actually changed since 03:17.'),
