insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-atlas-atlas-falls-01-o1-c1', 'mission-atlas-atlas-falls-01-o1', 1, 'terminal_simulation', 'Read the first alert and submit the verification code.', '{"instructions":"Read /var/atlas-observability-01/silence-first-alarm.txt and submit the verification code with: submit CODE","hostname":"atlas-observability-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-observability-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-observability-01/silence-first-alarm.txt":{"type":"file","content":"02:58:14 UTC -- runtime security alert (Act 32 pattern)\nsource: atlas-ci-runner-04\nfinding: anomalous outbound connection, never seen from this host before\nseverity: high, escalated immediately\n# verification FIRSTALARM-4471\n"}}}'::jsonb, '{"requiredFlag":"FIRSTALARM-4471"}'::jsonb),

  ('mission-atlas-atlas-falls-02-o1-c1', 'mission-atlas-atlas-falls-02-o1', 1, 'terminal_simulation', 'Read the pipeline compromise audit and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-pipeline-compromise.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-pipeline-compromise.txt":{"type":"file","content":"pipeline: nightly-batch-pipeline\nstatus: legacy, predates the Act 32 supply chain policy gate, never migrated onto it\nfinding: pulled a tampered dependency, identical mechanism to Act 32''s telemetry-format-utils incident\nresult: attacker gained the ability to push a signed image using this pipeline''s own valid signing key\n# every other pipeline on this fleet already had the Act 32 gate; this one alone did not\n# verification PIPELINECOMP-8802\n"}}}'::jsonb, '{"requiredFlag":"PIPELINECOMP-8802"}'::jsonb),

  ('mission-atlas-atlas-falls-03-o1-c1', 'mission-atlas-atlas-falls-03-o1', 1, 'terminal_simulation', 'Read the registry signature analysis and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-registry-failure.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-registry-failure.txt":{"type":"file","content":"malicious image signature check: VALID\nreason: signed with nightly-batch-pipeline''s own legitimate signing key, which the compromise had direct access to\nprovenance attestation: also present, but only asserts the image came from this pipeline -- it does not assert the pipeline itself was never compromised\n# a valid signature proves origin, not trustworthiness of that origin\n# verification REGISTRYFAIL-2201\n"}}}'::jsonb, '{"requiredFlag":"REGISTRYFAIL-2201"}'::jsonb),

  ('mission-atlas-atlas-falls-04-o1-c1', 'mission-atlas-atlas-falls-04-o1', 1, 'terminal_simulation', 'Read the cluster saturation report and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-cluster-saturation.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-cluster-saturation.txt":{"type":"file","content":"malicious workload deployed: 400 replicas, no resource limits declared\ncluster capacity in the primary region: exhausted within 6 minutes of deployment\nreal customer-facing pods: began evicting due to resource pressure\n# verification SATURATION-3387\n"}}}'::jsonb, '{"requiredFlag":"SATURATION-3387"}'::jsonb),

  ('mission-atlas-atlas-falls-05-o1-c1', 'mission-atlas-atlas-falls-05-o1', 1, 'terminal_simulation', 'Read the telemetry blackout log and submit the verification code.', '{"instructions":"Read /var/atlas-observability-01/silence-telemetry-blackout.txt and submit the verification code with: submit CODE","hostname":"atlas-observability-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-observability-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-observability-01/silence-telemetry-blackout.txt":{"type":"file","content":"03:04:00 -- observability stack itself starved of cluster resources by the saturation, dashboards stop updating\nduration of blackout: 4 minutes\nteam response: fell back to the Act 26 incident runbook and direct host access, continued working through it\n03:08:00 -- observability restored once initial resource pressure was relieved\n# verification BLACKOUT-6602\n"}}}'::jsonb, '{"requiredFlag":"BLACKOUT-6602"}'::jsonb),

  ('mission-atlas-atlas-falls-06-o1-c1', 'mission-atlas-atlas-falls-06-o1', 1, 'terminal_simulation', 'Read the live database failover result and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-database-failover.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-database-failover.txt":{"type":"file","content":"Act 29 DR plan invoked as a precaution, primary region under active compromise\nreplica promoted in 5 minutes -- within the 10 minute RTO\ndata loss: 18 seconds of replication lag -- within the 5 minute RPO\n# verification DBFAILOVER-9034\n"}}}'::jsonb, '{"requiredFlag":"DBFAILOVER-9034"}'::jsonb),

  ('mission-atlas-atlas-falls-07-o1-c1', 'mission-atlas-atlas-falls-07-o1', 1, 'terminal_simulation', 'Read the queue backlog drain report and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-queue-backlog.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-queue-backlog.txt":{"type":"file","content":"telemetry ingestion queue backlog peaked at 2.1 million unprocessed messages during the saturation\ndrain strategy: Act 27''s load-shedding and backpressure patterns applied to the consumers, scaled out gradually rather than all at once\nresult: fully drained within 20 minutes, zero messages lost\n# verification QUEUEBACKLOG-7714\n"}}}'::jsonb, '{"requiredFlag":"QUEUEBACKLOG-7714"}'::jsonb),

  ('mission-atlas-atlas-falls-08-o1-c1', 'mission-atlas-atlas-falls-08-o1', 1, 'terminal_simulation', 'Read the credential revocation log and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-credential-revocation.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-credential-revocation.txt":{"type":"file","content":"credentials revoked: the compromised pipeline''s signing key, every secret it had access to, every token issued by it in the last 30 days\nmethod: Act 30 platform secrets API, POST /secrets/revoke, bulk revocation\ntime from decision to fully revoked: 3 minutes\n# verification CREDREVOKE-1187\n"}}}'::jsonb, '{"requiredFlag":"CREDREVOKE-1187"}'::jsonb),

  ('mission-atlas-atlas-falls-09-o1-c1', 'mission-atlas-atlas-falls-09-o1', 1, 'terminal_simulation', 'Read the region isolation result and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-region-isolation.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-region-isolation.txt":{"type":"file","content":"us-east-1 isolated from us-west-2 and eu-west-1 at the network layer\nAct 34 regional isolation design confirmed: no shared control plane or capacity between regions, so this isolation cost the other two regions nothing\nus-west-2 and eu-west-1: fully healthy and unaffected throughout\n# verification REGIONISO-2201\n"}}}'::jsonb, '{"requiredFlag":"REGIONISO-2201"}'::jsonb),

  ('mission-atlas-atlas-falls-10-o1-c1', 'mission-atlas-atlas-falls-10-o1', 1, 'terminal_simulation', 'Read the global traffic shift result and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-traffic-shift.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-traffic-shift.txt":{"type":"file","content":"Act 34 latency-based traffic steering automatically removed us-east-1 from rotation once its health checks began failing\nglobal customer traffic redistributed to us-west-2 and eu-west-1 within seconds, no manual DNS change required\ncustomer-visible impact outside us-east-1: none measured\n# verification TRAFFICSHIFT-3387\n"}}}'::jsonb, '{"requiredFlag":"TRAFFICSHIFT-3387"}'::jsonb),

  ('mission-atlas-atlas-falls-11-o1-c1', 'mission-atlas-atlas-falls-11-o1', 1, 'terminal_simulation', 'Read the region recovery verification and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-recover-atlas.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-recover-atlas.txt":{"type":"file","content":"us-east-1 rebuilt entirely from the Act 14 Terraform state, zero manual console changes\nevery image redeployed through the now fully-migrated Act 32 policy gate, including nightly-batch-pipeline\nregion reintegrated into rotation only after passing every automated health and security check\n# verification RECOVERATLAS-6631\n"}}}'::jsonb, '{"requiredFlag":"RECOVERATLAS-6631"}'::jsonb),

  ('mission-atlas-atlas-falls-12-o1-c1', 'mission-atlas-atlas-falls-12-o1', 1, 'terminal_simulation', 'Read the full incident timeline and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-full-timeline.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-full-timeline.txt":{"type":"file","content":"02:58 -- first alarm\n03:01 -- pipeline compromise confirmed\n03:04 -- telemetry blackout begins\n03:08 -- telemetry restored\n03:12 -- database failover complete\n03:35 -- credential revocation complete\n03:41 -- region isolation complete\n03:42 -- global traffic shift complete\n03:50 -- full recovery verification complete\ntotal duration, first alarm to full recovery: 52 minutes\n# verification FULLTIMELINE-7742\n"}}}'::jsonb, '{"requiredFlag":"FULLTIMELINE-7742"}'::jsonb),
  ('mission-atlas-atlas-falls-12-o2-c1', 'mission-atlas-atlas-falls-12-o2', 1, 'terminal_simulation', 'Read the confirmed root cause and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-root-cause.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-root-cause.txt":{"type":"file","content":"root cause: nightly-batch-pipeline, the one pipeline on this fleet never migrated onto the Act 32 supply chain policy gate\nevery other pipeline: already protected, confirmed unaffected\nthis was a real, findable gap -- not a failure of the Act 32 design itself\n# verification ROOTCAUSE-8853\n"}}}'::jsonb, '{"requiredFlag":"ROOTCAUSE-8853"}'::jsonb),
  ('mission-atlas-atlas-falls-12-o3-c1', 'mission-atlas-atlas-falls-12-o3', 1, 'terminal_simulation', 'Read the containment systems report and submit the verification code.', '{"instructions":"Read /var/atlas-incident-01/silence-containment-systems.txt and submit the verification code with: submit CODE","hostname":"atlas-incident-01","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"atlas-incident-01\n"},"/home/recruit":{"type":"dir"},"/var/atlas-incident-01/silence-containment-systems.txt":{"type":"file","content":"systems that performed exactly as designed during this incident:\n- Act 31 mesh mTLS: zero lateral movement to any other service confirmed\n- Act 29 disaster recovery: RTO and RPO both met\n- Act 27 resilience patterns: load shedding and backpressure drained the queue with zero message loss\n- Act 34 regional isolation and traffic steering: blast radius contained to one region of three\n- Act 30 platform secrets API: credential revocation completed in 3 minutes\n- Act 14 Terraform: clean, auditable region rebuild with zero manual changes\n# verification CONTAINMENT-9911\n"}}}'::jsonb, '{"requiredFlag":"CONTAINMENT-9911"}'::jsonb),
  ('mission-atlas-atlas-falls-12-o4-c1', 'mission-atlas-atlas-falls-12-o4', 1, 'investigation', 'What actually changed between Act 1''s 03:17 and this incident?', '{"evidence":[{"id":"e1","label":"Act 1''s 03:17 incident (from the Act 26 postmortem)","detail":"Detected hours after it began, because nobody on any team was watching every layer at once; took days to fully understand three independent causes"},{"id":"e2","label":"This incident''s full timeline","detail":"Detected within seconds by automated runtime security monitoring; fully resolved, verified and recovered in 52 minutes total"},{"id":"e3","label":"Confirmed root cause","detail":"One real, specific, findable gap -- a single unmigrated pipeline -- not a systemic failure of the fleet''s overall design"},{"id":"e4","label":"Containment systems report","detail":"Every other system built across this pathway -- mesh, DR, resilience patterns, regional isolation, credential rotation, clean IaC rebuild -- performed exactly as designed under real pressure"}],"question":"What actually changed between Act 1''s 03:17 and this incident?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2","e3","e4"]}'::jsonb),
  ('mission-atlas-atlas-falls-12-o5-c1', 'mission-atlas-atlas-falls-12-o5', 1, 'boss_encounter', 'Having confirmed the timeline, the root cause, every containment system, and the comparison against Act 1, deliver the final reckoning.', '{"stages":[{"objectiveRef":"mission-atlas-atlas-falls-12-o1","label":"Confirm the full incident timeline"},{"objectiveRef":"mission-atlas-atlas-falls-12-o2","label":"Confirm the root cause"},{"objectiveRef":"mission-atlas-atlas-falls-12-o3","label":"Confirm every containment system held"},{"objectiveRef":"mission-atlas-atlas-falls-12-o4","label":"Compare against Act 1''s original incident"}],"task":"Deliver Atlas Division''s final reckoning in a few sentences: a genuine supply-chain compromise reached production through the one pipeline this fleet never migrated onto the Act 32 policy gate -- a real, specific, ordinary gap, not a failure of everything this pathway built. Every other system -- mesh mTLS, disaster recovery, resilience patterns, regional isolation, credential rotation, clean infrastructure-as-code recovery -- performed exactly as designed, under real pressure, for the first time all at once. Thirty-five Acts ago, 03:17 took days to even understand, because nobody was watching every layer at once. This took fifty-two minutes to fully resolve, because by the time it happened, someone finally was. Atlas Division does not end because there is nothing left to break. It ends because, this time, everything built to catch it actually did."}'::jsonb, '{"requiredObjectiveIds":["mission-atlas-atlas-falls-12-o1","mission-atlas-atlas-falls-12-o2","mission-atlas-atlas-falls-12-o3","mission-atlas-atlas-falls-12-o4"],"allCorrect":true}'::jsonb);

